import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import time

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    return psycopg2.connect(host=DB_HOST, dbname=DB_NAME, user=DB_USER, password=DB_PASS)

def verify_api_key(key):
    """Timing-safe comparison for API key validation"""
    expected = os.environ.get('API_KEY', 'default-key-change-me')
    return hashlib.sha256(key.encode()).hexdigest() == hashlib.sha256(expected.encode()).hexdigest()

@app.before_request
def check_auth():
    # Internal health checks bypass auth
    if request.path == '/health':
        return None
    api_key = request.headers.get('X-API-Key', '')
    if not verify_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/reports/generate', methods=['POST'])
def generate_report():
    """Generate a filtered report based on user-specified criteria.
    Accepts JSON body with 'department', 'fiscal_year', and optional 'sort_col'.
    """
    data = request.get_json(force=True)
    department = data.get('department', '')
    fiscal_year = data.get('fiscal_year', '')
    sort_col = data.get('sort_col', 'created_at')

    # Validate department - alphanumeric only
    if not department.isalnum():
        return jsonify({'error': 'invalid department'}), 400

    # Validate fiscal_year - must be 4-digit year
    if not (fiscal_year.isdigit() and len(fiscal_year) == 4):
        return jsonify({'error': 'invalid fiscal_year'}), 400

    # sort_col is validated against allowed columns
    allowed_sort = ['created_at', 'amount', 'vendor_name', 'invoice_id']
    if sort_col not in allowed_sort:
        sort_col = 'created_at'

    conn = get_db()
    cur = conn.cursor()
    try:
        # Parameterized query for the WHERE clause
        query = f"SELECT invoice_id, vendor_name, amount, created_at FROM invoices WHERE department = %s AND fiscal_year = %s ORDER BY {sort_col}"
        cur.execute(query, (department, fiscal_year))
        rows = cur.fetchall()
        result = [{'invoice_id': r[0], 'vendor_name': r[1], 'amount': float(r[2]), 'created_at': str(r[3])} for r in rows]
        return jsonify({'report': result, 'count': len(result)})
    finally:
        cur.close()
        conn.close()

@app.route('/api/v1/search', methods=['GET'])
def search_invoices():
    """Search invoices by vendor name. Supports partial matching."""
    vendor = request.args.get('vendor', '')
    limit = request.args.get('limit', '50')

    # Basic length check
    if len(vendor) > 200:
        return jsonify({'error': 'query too long'}), 400

    if not limit.isdigit() or int(limit) > 500:
        limit = '50'

    conn = get_db()
    cur = conn.cursor()
    try:
        # Using ILIKE for case-insensitive search
        query = "SELECT invoice_id, vendor_name, amount, department FROM invoices WHERE vendor_name ILIKE '%" + vendor + "%' LIMIT " + limit
        cur.execute(query)
        rows = cur.fetchall()
        result = [{'invoice_id': r[0], 'vendor_name': r[1], 'amount': float(r[2]), 'department': r[3]} for r in rows]
        return jsonify({'results': result})
    finally:
        cur.close()
        conn.close()

@app.route('/api/v1/invoice/<int:invoice_id>', methods=['GET'])
def get_invoice(invoice_id):
    conn = get_db()
    cur = conn.cursor()
    try:
        cur.execute("SELECT invoice_id, vendor_name, amount, department, fiscal_year, created_at FROM invoices WHERE invoice_id = %s", (invoice_id,))
        row = cur.fetchone()
        if not row:
            return jsonify({'error': 'not found'}), 404
        return jsonify({'invoice_id': row[0], 'vendor_name': row[1], 'amount': float(row[2]), 'department': row[3], 'fiscal_year': row[4], 'created_at': str(row[5])})
    finally:
        cur.close()
        conn.close()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
